// Filtra, normaliza y deja traza. Un solo lugar donde mirar cuando alguien
// pregunte "por que no me llego el recordatorio?".
const filas = $input.all().filter((item) => item.json.destinatario);

console.log(`[Recordatorio 21:00] Sedes sin movimientos hoy: ${filas.length}`);

if (filas.length === 0) {
  return [];
}

return filas.map((item) => {
  const bruto = String(item.json.destinatario);

  // Un BSUID (CO.1710763673557397) va tal cual: quitarle el prefijo lo rompe.
  // Un telefono si se limpia, porque Meta lo exige en digitos.
  const esIdentidad = bruto.includes('.');
  const destinatario = esIdentidad ? bruto : bruto.replace(/\D/g, '');

  const sede = String(item.json.sede);

  // Meta exige el numero en formato internacional. Un movil colombiano completo
  // tiene 12 digitos (57 + 10). Sin el prefijo, el envio se acepta y nunca llega,
  // asi que conviene verlo en el log y arreglar el dato en la base.
  if (!esIdentidad && destinatario.length < 11) {
    console.error(
      `[AVISO] La sede "${sede}" tiene el telefono sin codigo de pais: ${destinatario}. Corregir en Sede.telefono (ej. 57${destinatario}).`,
    );
  }

  const contacto = String(item.json.contacto || '').split(' ')[0] || 'por aqui';
  const negocio = String(item.json.negocio);

  console.log(
    `[Recordatorio 21:00] → ${negocio} / ${sede} (${esIdentidad ? bruto : '***' + destinatario.slice(-4)})`,
  );

  return {
    json: {
      sedeId: item.json.sede_id,
      negocio,
      sede,
      // Lo que ve el usuario. Se nombra la sede porque un mismo duenno puede
      // tener varias, cada una con su linea, y si no no sabria cual es cual.
      destino: `${negocio} (${sede})`,
      destinatario,
      contacto,
    },
  };
});

// No se corta el workflow por un envío fallido: se registra y se sigue con
// los demás negocios.
for (const item of $input.all()) {
  const detalle = JSON.stringify(item.json).slice(0, 800);
  console.error('[Recordatorio 21:00] ERROR de envío:', detalle);
}
return $input.all();
